Функция СводкаКлиентовДляЗащиты(Левое = Истина,СчитатьСтрокуСоединения = Ложь) Экспорт
    Коды = Новый Массив; Коды.Добавить("A8C1"); Коды.Добавить("A8C2"); Коды.Добавить("A8C3");
    Соединение = ?(Левое,"ЛЕВОЕ СОЕДИНЕНИЕ","ВНУТРЕННЕЕ СОЕДИНЕНИЕ");
    Счётчик = ?(СчитатьСтрокуСоединения,"КОЛИЧЕСТВО(*)","КОЛИЧЕСТВО(З.Ссылка)");
    Текст = "ВЫБРАТЬ К.Ссылка КАК Клиент," + Счётчик + " КАК Заявок,ЕСТЬNULL(СУММА(З.ДлительностьМинут),0) КАК Минуты ИЗ Справочник.Клиенты КАК К " + Соединение + " Документ.ЗаявкаУслуги КАК З ПО К.Ссылка = З.Клиент ГДЕ К.Код В (&Коды) СГРУППИРОВАТЬ ПО К.Ссылка";
    Запрос = Новый Запрос(Текст); Запрос.УстановитьПараметр("Коды",Коды);
    Возврат Запрос.Выполнить().Выгрузить();
КонецФункции

Функция ОпытПотерянногоКлиента() Экспорт
    Внутреннее = СводкаКлиентовДляЗащиты(Ложь);
    Левое = СводкаКлиентовДляЗащиты();
    Пустой = Справочники.Клиенты.НайтиПоКоду("A8C3");
    СтрокаПустого = Левое.Найти(Пустой,"Клиент");
    Возврат Новый Структура("ВнутреннихСтрок,ЛевыхСтрок,ПустойВозвращён,ЗаявокПустого,МинутВсего",Внутреннее.Количество(),Левое.Количество(),СтрокаПустого <> Неопределено,СтрокаПустого.Заявок,Левое.Итог("Минуты"));
КонецФункции

Функция ОпытЛишнейЕдиницы() Экспорт
    Пустой = Справочники.Клиенты.НайтиПоКоду("A8C3");
    Неверная = СводкаКлиентовДляЗащиты(Истина,Истина);
    Верная = СводкаКлиентовДляЗащиты();
    ОшибочнаяСтрока = Неверная.Найти(Пустой,"Клиент");
    ИсправленнаяСтрока = Верная.Найти(Пустой,"Клиент");
    Возврат Новый Структура("НеверныхЗаявок,ВерныхЗаявок,ТотЖеПустой,ВсегоЗаявок,МинутВсего",ОшибочнаяСтрока.Заявок,ИсправленнаяСтрока.Заявок,ОшибочнаяСтрока.Клиент = ИсправленнаяСтрока.Клиент,Верная.Итог("Заявок"),Верная.Итог("Минуты"));
КонецФункции

Процедура ПриНачалеРаботыСистемы()
    Итог = УчебнаяИтоговая.ОпытПотерянногоКлиента();
    Сообщить("Клиентов с INNER JOIN: " + Строка(Итог.ВнутреннихСтрок));
    Сообщить("Клиентов с LEFT JOIN: " + Строка(Итог.ЛевыхСтрок));
    Сообщить("Пустой клиент возвращён: " + Строка(Итог.ПустойВозвращён));
    Сообщить("Заявок у пустого клиента: " + Строка(Итог.ЗаявокПустого));
    Сообщить("Минут всего: " + Строка(Итог.МинутВсего));
КонецПроцедуры

